const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const input=$('#claimInput'), toast=$('#toast');
const demoText='社群貼文宣稱：「最新研究已證實，每天喝兩杯咖啡能讓記憶力提升 40%，而且對所有年齡層都有效。」';
const demoClaims=[
 {text:'最新研究已證實，每天喝兩杯咖啡能讓記憶力提升 40%。',status:'MISLEADING',label:'脈絡不全',explanation:'示範資料顯示，原始研究只觀察特定測驗表現，且未支持「提升 40%」這個數字。貼文把有限的關聯性結果轉述為確定效果。',evidence:[{title:'示範：原始研究摘要',type:'研究資料',excerpt:'研究僅指出部分受試者在一項記憶測驗中出現改善，沒有報告 40% 的整體提升。'},{title:'示範：大學新聞稿',type:'機構說明',excerpt:'新聞稿使用「可能有助於」的語氣，並提醒結果仍需更多研究。'}]},
 {text:'這項效果已獲得最新研究證實。',status:'SUPPORTED',label:'部分支持',explanation:'示範資料中確實存在相關研究，但研究支持的是有限條件下的觀察結果，不等同於貼文描述的廣泛效果。',evidence:[{title:'示範：研究發表頁面',type:'第一手來源',excerpt:'研究確實已發表，研究對象與測量方式有明確限制。'}]},
 {text:'喝咖啡對所有年齡層都有效。',status:'UNVERIFIED',label:'證據不足',explanation:'示範來源沒有涵蓋所有年齡層，現有資料不足以把結果推廣到整體人口。',evidence:[]}
];
function showToast(msg){toast.textContent=msg;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2200)}
function route(id){$$('.view').forEach(v=>v.classList.remove('active-view'));$('#'+id).classList.add('active-view');$$('.topbar nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+id));window.scrollTo({top:0,behavior:'smooth'});if(id==='history') renderHistory()}
function setMode(mode){$$('.mode-tab').forEach(b=>{let on=b.dataset.mode===mode;b.classList.toggle('active',on);b.setAttribute('aria-selected',on)});input.placeholder=mode==='url'?'貼上文章網址，例如：https://example.com/article':'例如：網路文章聲稱，某項政策將於 10 月 1 日生效，並影響 200 萬人……'}
$$('.mode-tab').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));
input.addEventListener('input',()=>{$('#charCount').textContent=`${input.value.length.toLocaleString()} / 5,000 字`;if(input.value.length>5000)input.value=input.value.slice(0,5000)});
$('#clearBtn').onclick=()=>{input.value='';input.dispatchEvent(new Event('input'));input.focus()};
$('#exampleBtn').onclick=()=>{setMode('text');input.value=demoText;input.dispatchEvent(new Event('input'));input.focus();showToast('已載入示範案例')};
$$('.back-btn').forEach(b=>b.onclick=()=>route('home'));
$$('.topbar nav a,.brand').forEach(a=>a.addEventListener('click',e=>{const id=a.hash?.slice(1);if(id&&$('#'+id)){e.preventDefault();route(id)}}));
$('#themeBtn').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('cl-theme',document.body.classList.contains('dark')?'dark':'light')};
if(localStorage.getItem('cl-theme')==='dark')document.body.classList.add('dark');
function escapeHTML(s){return s.replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function groupedCounts(claims){return claims.reduce((a,c)=>{if(c.status==='SUPPORTED')a.SUPPORTED++;else if(['MISLEADING','CONTRADICTED','OUTDATED'].includes(c.status))a.MISLEADING++;else a.UNVERIFIED++;return a},{SUPPORTED:0,MISLEADING:0,UNVERIFIED:0})}
function evidenceHTML(e){const meta=[e.publisher,e.publishedAt,e.type].filter(Boolean).map(escapeHTML).join(' · ');return `<article class="evidence-card"><header><h4>${escapeHTML(e.title)}</h4><span class="source-type">${escapeHTML(e.relationship||e.type||'來源')}</span></header>${meta?`<small>${meta}</small>`:''}<p>${escapeHTML(e.excerpt)}</p>${e.url?`<a href="${escapeHTML(e.url)}" target="_blank" rel="noopener noreferrer">開啟原始來源 ↗</a>`:'<span class="source-type">示意來源 · 無外部連結</span>'}</article>`}
function renderReport(claims,isDemo,source,title='證據查核報告',analyzedAt=new Date().toISOString()){const counts=groupedCounts(claims);$('#reportHeading').textContent=title;$('#claimTotal').textContent=claims.length;$('#supportedCount').textContent=counts.SUPPORTED;$('#misleadingCount').textContent=counts.MISLEADING;$('#unverifiedCount').textContent=counts.UNVERIFIED;$('#reportDate').textContent=`分析時間：${new Intl.DateTimeFormat('zh-TW',{dateStyle:'long',timeStyle:'short'}).format(new Date(analyzedAt))}`;$('#claimsList').innerHTML=(isDemo?'<div class="demo-flag">這是互動示範報告。下列來源卡是用來展示介面與查核邏輯的示意資料，不是可開啟的真實引文。</div>':'')+claims.map((c,i)=>`<article class="claim-card"><div class="claim-top"><span class="claim-num">主張 ${String(i+1).padStart(2,'0')}</span><h3>「${escapeHTML(c.text)}」</h3><span class="status ${['SUPPORTED','MISLEADING','UNVERIFIED'].includes(c.status)?c.status.toLowerCase():'misleading'}">${escapeHTML(c.label)}</span></div><div class="claim-body"><p>${escapeHTML(c.explanation)}</p><div class="evidence-label">相關證據 · ${c.evidence.length}</div>${c.evidence.length?`<div class="evidence-grid">${c.evidence.map(evidenceHTML).join('')}</div>`:'<div class="evidence-card"><p>尚未取得足夠且可驗證的獨立來源。此項目維持「證據不足」。</p></div>'}</div></article>`).join('');$('#mutationSection').style.display=isDemo?'block':'none';const rec={id:Date.now().toString(36),title:source.slice(0,80),reportTitle:title,date:analyzedAt,claims,isDemo};const hist=JSON.parse(localStorage.getItem('cl-history')||'[]');hist.unshift(rec);localStorage.setItem('cl-history',JSON.stringify(hist.slice(0,12)));location.hash='report='+rec.id;route('report')}
async function analyze(){const text=input.value.trim();if(!text){showToast('請先貼上要查核的文字或網址');input.focus();return}route('loading');const steps=$$('#pipeline li');steps.forEach(s=>s.className='');if(text===demoText){for(const step of steps){step.classList.add('running');await new Promise(r=>setTimeout(r,320));step.className='done'}renderReport(demoClaims,true,text);return}let timer=0;const advance=()=>{if(timer<steps.length-1){if(timer>0)steps[timer-1].className='done';steps[timer].className='running';timer++}};advance();const pulse=setInterval(advance,2500);try{const res=await fetch('/api/analyze',{method:'POST',headers:{'content-type':'application/json','accept':'application/json'},body:JSON.stringify({input:text})});const raw=await res.text();let data;try{data=JSON.parse(raw)}catch{throw new Error(res.status===504?'分析時間較長，請再試一次':'伺服器暫時沒有回傳有效結果，請稍後再試')}if(!res.ok)throw new Error(data.error||'分析失敗');if(!data?.report?.claims?.length)throw new Error('找不到可顯示的查核結果，請重新嘗試');clearInterval(pulse);steps.forEach(s=>s.className='done');renderReport(data.report.claims,false,text,data.report.title,data.analyzedAt)}catch(err){clearInterval(pulse);route('home');showToast(err.message||'分析失敗，請稍後再試')}}
$('#analyzeBtn').onclick=analyze;
function renderHistory(){const list=$('#historyList'),hist=JSON.parse(localStorage.getItem('cl-history')||'[]');list.innerHTML=hist.length?hist.map(h=>`<button class="history-card" data-id="${h.id}"><h3>${escapeHTML(h.title)}${h.title.length>=46?'…':''}</h3><p>${new Date(h.date).toLocaleString('zh-TW')} · ${h.claims.length} 項主張</p><span>${h.isDemo?'示範報告':'證據不足'}</span></button>`).join(''):'<div class="empty">尚無查核紀錄。完成第一次分析後，報告會出現在這裡。</div>';$$('.history-card').forEach(b=>b.onclick=()=>{const h=hist.find(x=>x.id===b.dataset.id);if(h){renderExisting(h)}})}
function renderExisting(h){const counts=groupedCounts(h.claims);$('#reportHeading').textContent=h.reportTitle||'證據查核報告';$('#claimTotal').textContent=h.claims.length;$('#supportedCount').textContent=counts.SUPPORTED;$('#misleadingCount').textContent=counts.MISLEADING;$('#unverifiedCount').textContent=counts.UNVERIFIED;$('#reportDate').textContent=`分析時間：${new Date(h.date).toLocaleString('zh-TW')}`;$('#claimsList').innerHTML=(h.isDemo?'<div class="demo-flag">這是互動示範報告，來源為介面示意資料。</div>':'')+h.claims.map((c,i)=>`<article class="claim-card"><div class="claim-top"><span class="claim-num">主張 ${String(i+1).padStart(2,'0')}</span><h3>「${escapeHTML(c.text)}」</h3><span class="status ${['SUPPORTED','MISLEADING','UNVERIFIED'].includes(c.status)?c.status.toLowerCase():'misleading'}">${escapeHTML(c.label)}</span></div><div class="claim-body"><p>${escapeHTML(c.explanation)}</p><div class="evidence-label">相關證據 · ${c.evidence.length}</div>${c.evidence.length?`<div class="evidence-grid">${c.evidence.map(evidenceHTML).join('')}</div>`:'<div class="evidence-card"><p>尚未取得足夠且可驗證的獨立來源。</p></div>'}</div></article>`).join('');$('#mutationSection').style.display=h.isDemo?'block':'none';location.hash='report='+h.id;route('report')}
$('#shareBtn').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);showToast('報告連結已複製')}catch{showToast('請從瀏覽器網址列複製連結')}};
const match=location.hash.match(/^#report=(.+)$/);if(match){const h=JSON.parse(localStorage.getItem('cl-history')||'[]').find(x=>x.id===match[1]);if(h)renderExisting(h)}
